package net.spell_engine.api.item.trinket; import dev.emi.trinkets.api.*; import net.minecraft.entity.*; import net.minecraft.entity.player.PlayerEntity; import net.minecraft.item.*; import net.minecraft.sound.SoundEvent; import net.minecraft.util.Identifier; public class SpellBookTrinketItem extends TrinketItem implements SpellBookItem { private final Identifier poolId; public static final Identifier EQUIP_SOUND_ID=new Identifier("spell_engine","spellbook_equip"); public static final SoundEvent EQUIP_SOUND=SoundEvent.of(EQUIP_SOUND_ID); public SpellBookTrinketItem(Identifier id,Settings s){super(s);poolId=id;}public boolean isEnchantable(ItemStack s){return false;}public Identifier getPoolId(){return poolId;}public boolean canUnequip(ItemStack s,SlotReference slot,LivingEntity e){boolean cd=e instanceof PlayerEntity p&&p.getItemCooldownManager().isCoolingDown(s.getItem());return super.canUnequip(s,slot,e)&&!cd;}public void onEquip(ItemStack s,SlotReference slot,LivingEntity e){super.onEquip(s,slot,e);if(e.getWorld().isClient&&e.age>100)e.playSound(EQUIP_SOUND,1,1);} }
